mapper.select:
select * from eb_store_product_reply pr left join eb_user as u on pr.uid = u.uid left join eb_store_product as p on pr.product_id = p.id where p.is_del = 0 and pr.is_del = 0
and p.store_name like CONCAT('%',#{productSearch},'%')
and pr.is_reply = #{isReply}
and pr.create_time between #{startTime} and #{endTime}
and ( pr.uid like CONCAT('%',#{keywords},'%') or u.nickname like CONCAT('%',#{keywords},'%') or u.phone like CONCAT('%',#{keywords},'%') )
and pr.uid = #{uid}
and u.nickname like CONCAT('%',#{nickname},'%')
and u.phone like CONCAT('%',#{phone},'%')
order by pr.id desc
